## Why This Is Asked

This question evaluates practical concurrency control skills involving multiple producers, bounded buffers, and latency guarantees with a simple priority policy. The solution tests real-world challenges like starvation prevention and graceful shutdown coordination.

## Key Concepts

- Dual-queue architecture for priority separation
- Mutual exclusion and condition synchronization
- Backpressure mechanisms for flow control
- Aging algorithms to prevent starvation
- Graceful shutdown patterns with resource cleanup

## Code Example

```javascript
// Pseudo sketch of data structures and worker loop
class Task { 
  constructor(priority) { 
    this.priority = priority; 
    this.timestamp = Date.now();
  } 
}

class PriorityQueue {
  constructor(capacity) {
    this.capacity = capacity;
    this.highQueue = [];
    this.normalQueue = [];
    this.mutex = new Mutex();
    this.notEmpty = new ConditionVariable();
    this.notFull = new ConditionVariable();
    this.shutdown = false;
    this.agingThreshold = 5000; // 5 seconds
  }

  async enqueue(task) {
    await this.mutex.lock();
    while (this.size() >= this.capacity && !this.shutdown) {
      await this.notFull.wait();
    }

    if (task.priority === 'high') {
      this.highQueue.push(task);
    } else {
      this.normalQueue.push(task);
    }

    this.notEmpty.signal();
    this.mutex.unlock();
  }

  async dequeue() {
    await this.mutex.lock();
    while (this.size() === 0 && !this.shutdown) {
      await this.notEmpty.wait();
    }

    if (this.shutdown && this.size() === 0) {
      this.mutex.unlock();
      return null;
    }

    this.checkAging();

    let task;
    if (this.highQueue.length > 0) {
      task = this.highQueue.shift();
    } else if (this.normalQueue.length > 0) {
      task = this.normalQueue.shift();
    }

    this.notFull.signal();
    this.mutex.unlock();
    return task;
  }

  checkAging() {
    const now = Date.now();
    this.normalQueue = this.normalQueue.filter(task => {
      if (now - task.timestamp > this.agingThreshold) {
        this.highQueue.push(task);
        return false;
      }
      return true;
    });
  }

  size() {
    return this.highQueue.length + this.normalQueue.length;
  }

  async shutdown() {
    await this.mutex.lock();
    this.shutdown = true;
    this.notEmpty.broadcast();
    this.notFull.broadcast();
    this.mutex.unlock();
  }
}
```

## Test Plan

### Latency Testing
- Measure end-to-end processing time for high vs. normal priority tasks
- Verify high-priority tasks consistently achieve lower latency
- Test with varying load levels to validate priority guarantees

### Starvation Testing
- Generate continuous high-priority load and monitor normal task processing
- Verify aging mechanism promotes aged normal tasks
- Measure maximum wait time for normal tasks under sustained high load

### Graceful Shutdown Testing
- Initiate shutdown while tasks are processing
- Verify all in-flight tasks complete before worker termination
- Test with producers blocked on backpressure
- Confirm no resource leaks or deadlocks

## Why This Is Asked

This question evaluates the ability to design a low-latency, ordered broadcast path with backpressure and dynamic scaling for a high-traffic chat system—similar to workloads at Discord, Cloudflare, and data platforms.

## Key Concepts

- **Per-room ordering** via per-room sequence numbers or monotonically increasing room-level sequence IDs
- **Bounded queues** with backpressure signaling (e.g., pushback, drop policies)
- **Dynamic worker scaling** per room based on queue depth or throughput metrics
- **Event prioritization** and graceful degradation under load
- **Testing strategies** for concurrency, ordering guarantees, and failure scenarios

## Solution Overview

Use per-room sequence numbers and per-room FIFO buffers. Route events through a central bounded queue to a per-room dispatcher, then to pools of workers dedicated to each room. Maintain order by storing the global or room-level sequence number in each event and processing events in per-room priority queues ordered by this sequence number.

## Code Example

```go
package main

import (
	"context"
	"sync"
	"time"
)

type EventType int
const (
	EventTypeMessage EventType = iota
	EventTypeJoin
	EventTypeLeave
)

type Event struct {
	RoomID   string
	EventID  string
	Type     EventType
	Payload  string
	SeqNum   int64
}

type Room struct {
	ID           string
	mu           sync.RWMutex
	buffer       []Event
	capacity     int
	workers      int
	clients      map[chan<- Event]struct{}
	sequenceNum  int64
}

func NewRoom(id string, capacity int) *Room {
	return &Room{
		ID:       id,
		capacity: capacity,
		clients:  make(map[chan<- Event]struct{}),
	}
}

func (r *Room) PushEvent(e Event) bool {
	r.mu.Lock()
	defer r.mu.Unlock()

	if len(r.buffer) >= r.capacity {
		return r.handleBackpressure(e)
	}

	r.buffer = append(r.buffer, e)
	return true
}

func (r *Room) handleBackpressure(e Event) bool {
	if e.Type == EventTypeJoin || e.Type == EventTypeLeave {
		r.buffer = append(r.buffer, e)
		if len(r.buffer) > r.capacity {
			r.buffer = r.buffer[1:]
		}
		return true
	}
	return false
}

func (r *Room) Broadcast(ctx context.Context) {
	ticker := time.NewTicker(10 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			r.mu.RLock()
			if len(r.buffer) == 0 {
				r.mu.RUnlock()
				continue
			}
			event := r.buffer[0]
			r.buffer = r.buffer[1:]
			clients := make([]chan<- Event, 0, len(r.clients))
			for ch := range r.clients {
				clients = append(clients, ch)
			}
			r.mu.RUnlock()

			for _, ch := range clients {
				select {
				case ch <- event:
				default:
				}
			}
		}
	}
}

type Distributor struct {
	mu      sync.RWMutex
	rooms   map[string]*Room
	input   chan Event
	wg      sync.WaitGroup
	ctx     context.Context
	cancel  context.CancelFunc
}

func NewDistributor(bufferPerRoom int) *Distributor {
	ctx, cancel := context.WithCancel(context.Background())
	return &Distributor{
		rooms:  make(map[string]*Room),
		input:  make(chan Event, 10000),
		ctx:    ctx,
		cancel: cancel,
	}
}

func (d *Distributor) GetRoom(roomID string) *Room {
	d.mu.Lock()
	defer d.mu.Unlock()

	if room, ok := d.rooms[roomID]; ok {
		return room
	}

	room := NewRoom(roomID, 1000)
	d.rooms[roomID] = room
	d.wg.Add(1)
	go func() {
		defer d.wg.Done()
		room.Broadcast(d.ctx)
	}()
	return room
}

func (d *Distributor) Run() {
	for {
		select {
		case <-d.ctx.Done():
			return
		case event := <-d.input:
			room := d.GetRoom(event.RoomID)
			room.PushEvent(event)
		}
	}
}

func (d *Distributor) Publish(event Event) {
	select {
	case d.input <- event:
	default:
	}
}

func (d *Distributor) Shutdown() {
	d.cancel()
	close(d.input)
	d.wg.Wait()
}

func main() {
	d := NewDistributor(1000)
	go d.Run()

	d.Publish(Event{
		RoomID:  "room-1",
		EventID: "evt-1",
		Type:    EventTypeJoin,
		Payload: "user-1 joined",
	})

	time.Sleep(100 * time.Millisecond)
	d.Shutdown()
}
```

## Test Plan

1. **Ordering Tests**: Publish 1000 events per room out of order; verify they are delivered in sequence number order.
2. **Backpressure Tests**: Fill buffers to capacity; verify join/leave events are preserved while messages are dropped.
3. **Concurrency Tests**: Run 10 producers and 10 consumers per room simultaneously; check for race conditions and data races.
4. **Dynamic Scaling Tests**: Simulate burst traffic; verify worker count increases and decreases based on queue depth.
5. **Failure Recovery**: Kill rooms mid-broadcast; verify system continues operating and new rooms spawn correctly.
6. **Latency Tests**: Measure end-to-end latency under load; ensure p99 < 50ms for priority events.

## Why This Is Asked
Tests practical handling of multiple producers with prioritized fairness and backpressure in a simple, implementable pattern.

## Key Concepts
- Bounded queues and backpressure
- Priority with FIFO guarantees
- Semaphore-based flow control
- Testing ordering and deadlock avoidance

